contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 setupAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (setupAmount)); require(setupAmount <= 1000000000000000000000000000000);
        require(setupAmount > 0);
        require(address(this).balance >= setupAmount);

        c.multiplicate{value: setupAmount}(address(this)); if (__ESBMC_reverted()) return;

        uint256 contractPrior = address(c).balance;
        address owner = c.Owner(); if (__ESBMC_reverted()) return;
        uint256 ownerPrior = owner.balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted || (address(c).balance == 0 && owner.balance == ownerPrior + contractPrior));
    }
}

