pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(uint256 setupAmount) internal {
        setupAmount = bound(setupAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(setupAmount > 0);
        vm.assume(address(this).balance >= setupAmount);
        try c.multiplicate{value: setupAmount}(address(this)) {} catch { return; }
        uint256 contractPrior = address(c).balance;
        address owner;
        try c.Owner() returns (address __r) { owner = __r; } catch { return; }
        uint256 ownerPrior = owner.balance;
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || (address(c).balance == 0 && owner.balance == ownerPrior + contractPrior));
    }

    function testFuzz_run(uint256 setupAmount) public {
        _run(setupAmount);
    }

    receive() external payable {}
}
